import{z as A,x as o,o as n,c as B,q as r,j as t,D as e,d as l,s as p,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"CFL 泵引理","description":"","frontmatter":{"title":"CFL 泵引理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pumping-lemma-cfl.md","filePath":"cs/pumping-lemma-cfl.md","lastUpdated":1791413859000}'),d={name:"cs/pumping-lemma-cfl.md"};function C(m,a,F,c,D,u){const i=o("Mermaid");return n(),B("div",null,[a[2]||(a[2]=r('<h1 id="cfl-泵引理" tabindex="-1">CFL 泵引理 <a class="header-anchor" href="#cfl-泵引理" aria-label="Permalink to &quot;CFL 泵引理&quot;">​</a></h1><div class="epigraph"><p>足够长的上下文无关串，推导树上有可重复的树枝：两段子串可同时泵；破坏这对计数，就不是 CFL。</p><footer>—— 据 Bar-Hillel, Perles and Shamir, 1961；Sipser 整理</footer></div><p>上一课<a href="/cs/pushdown-automata">下推自动机</a>把 CFL 钉在单栈上，并点名 \\(a^nb^nc^n\\) 像是两根计数器。本课不重做 PDA 转移。缺口是负向工具：CFL 泵引理（以及何时必须用 Ogden）。正则泵是一段 \\(y\\)；这里是两段 \\(v,y\\)，对应树上一条可重复路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CNF 文法下，足够长的串的推导树必有一条长路径，某非终结符 \\(A\\) 重复。把上下两段切成 \\(uvwxy\\)，可泵 \\(uv^iwx^iy\\)。条件：\\(|vwx|\\le p\\)、\\(|vx|\\ge 1\\)。若对一切这种切法都能选 \\(i\\) 使结果掉出 \\(L\\)，则非 CFL。</p><p>\\(\\{a^nb^nc^n\\}\\)：泵只能动两种字母的计数（\\(vwx\\) 短），第三种对不上。\\(\\{ww\\}\\) 更滑，标准泵可能失败，Ogden 给位置打标记。本课以 \\(a^nb^nc^n\\) 为主靶。</p><h3 id="仍不是充要" tabindex="-1">仍不是充要 <a class="header-anchor" href="#仍不是充要" aria-label="Permalink to &quot;仍不是充要&quot;">​</a></h3><p>可泵的不必是 CFL。引理方向是 CFL \\(\\Rightarrow\\) 可泵。封闭性（与正则交仍 CFL）常与泵合用：先切出切片再泵。</p><p><span class="marginnote">Bar-Hillel et al. 同时给了正则与 CFL 泵。Sipser 强调 \\(v,x\\) 可以在串的两端。Ogden 1968 是加强版，本课点名不证。</span></p><p><span class="marginnote">直觉类比：正则泵像橡皮筋上夹一段可拉伸的段落；CFL 泵则是「两根针同时扎在串上」（\\(v\\) 与 \\(x\\)），两段要一起拉。为什么是两段？因为栈上一次「推入–弹出」配对，会在串上留下两处互为镜像的痕迹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取 \\(p\\) 为泵长度，\\(w=a^pb^pc^p\\)。对手切 \\(uvwxy\\)，讨论 \\(v,x\\) 覆盖哪些字母块：若只覆盖一种或两种，泵 \\(i=2\\) 破坏三者相等；不能三种都覆盖因为 \\(|vwx|\\le p\\)。不要用正则泵去泵 CFL——一段 \\(y\\) 不够同时动两处。</p><p><span class="marginnote">初学者最容易犯的就是最后这句：拿正则泵（只泵一段 \\(y\\)）去打 \\(a^nb^nc^n\\)，结果对手怎么切都不失败，于是误以为「引理失灵」。不是引理错了，是工具用错了——同时动两处计数，必须用两段 \\(v,x\\) 的 CFL 泵。</span></p>',13)),(n(),t(s,null,{default:e(()=>[p(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TREE%5B%22CNF%20%E6%8E%A8%E5%AF%BC%E6%A0%91%22%5D%20--%3E%20REP%5B%22%E9%9D%9E%E7%BB%88%E7%BB%93%E7%AC%A6%E9%87%8D%E5%A4%8D%22%5D%0A%20%20REP%20--%3E%20TWO%5B%22%E4%B8%A4%E6%AE%B5%20v%2C%20x%20%E5%8F%AF%E6%B3%B5%22%5D%0A%20%20TWO%20--%3E%20NEG%5B%22%E7%A0%B4%E5%9D%8F%E4%B8%89%E8%AE%A1%E6%95%B0%E5%88%99%E9%9D%9E%20CFL%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与正则交封闭：CFL \\(\\cap\\) 正则仍 CFL。证 \\(\\{a^nb^nc^n\\}\\) 常直接泵；证更脏的语言可先交 \\(a^*b^*c^*\\)。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"树的可重复对应栈上一段「推然后弹」的周期。单栈只有一层这样的配对，所以两个独立配对（\\(a^n b^n c^n d^n\\) 的另一种切法）也会失败。泵引理把「栈的局限」写成串上的组合陈述，不必画自动机。",-1)),a[6]||(a[6]=E("p",null,"二义性与是否 CFL 无关：固有二义语言仍是 CFL，泵不谈树是否唯一。",-1)),a[7]||(a[7]=E("p",null,"Ogden 引理允许你指定「要泵的位置」，用来打 \\(\\{ww\\}\\) 一类标准泵失败的例子。本课不写它的证明，只提醒：泵失败不等于是 CFL。CFL 与正则的交仍是 CFL，因此可先用正则「切出」\\(a^*b^*c^*\\) 再泵，避免串的其它垃圾破坏计数。",-1)),(n(),t(s,null,{default:e(()=>[p(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22w%20%3D%20a%5Ep%20b%5Ep%20c%5Ep%22%5D%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%20vwx%20%E9%95%BF%E5%BA%A6%E8%87%B3%E5%A4%9A%20p%22%5D%0A%20%20WIN%20--%3E%20Q%7B%22%E7%AA%97%E5%8F%A3%E7%BD%A9%E4%BD%8F%E5%93%AA%E4%BA%9B%E5%AD%97%E6%AF%8D%E5%9D%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%20a%20%E6%88%96%20a%20%E5%8A%A0%20b%22%7C%20P1%5B%22%E6%B3%B5%20i%3D2%20%E5%90%8E%20a%20b%20%E5%8F%98%E5%A4%9A%20c%20%E4%B8%8D%E5%8A%A8%20%E5%A4%B1%E9%85%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%20b%20%E6%88%96%20b%20%E5%8A%A0%20c%22%7C%20P2%5B%22%E6%B3%B5%E5%90%8E%20a%20%E8%AE%A1%E6%95%B0%E8%90%BD%E5%90%8E%20%E5%A4%B1%E9%85%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E6%83%B3%E5%90%8C%E6%97%B6%E7%BD%A9%20a%20%E4%B8%8E%20c%22%7C%20P3%5B%22%E4%B8%AD%E9%97%B4%E9%9A%94%E6%95%B4%E5%9D%97%20b%20%E7%AA%97%E5%8F%A3%E8%A3%85%E4%B8%8D%E4%B8%8B%22%5D%0A%20%20P1%20--%3E%20NO%5B%22%E4%BB%BB%E4%BD%95%E5%88%87%E6%B3%95%E9%83%BD%E5%AD%98%E5%9C%A8%20i%20%E4%BD%BF%E7%BB%93%E6%9E%9C%E5%87%BA%20L%20%E9%9D%9E%20CFL%22%5D%0A%20%20P2%20--%3E%20NO%0A%20%20P3%20--%3E%20NO%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">上图回答「为什么对 \\(a^nb^nc^n\\) 一泵就破」：代入数字，\\(p=4\\) 时窗口长至多 4，而每块恰好 4 个字母——窗口最多铺满一块，想同时碰到 \\(a\\) 和 \\(c\\) 就得吞下中间整块 \\(b\\)，超长。于是任何切法至多动两种计数，\\(i=2\\) 必失配。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Parikh 定理，不把 Ogden 全文写下。不引入 CSL 的泵。后课默认：排除 CFL 先泵 \\(a^nb^nc^n\\) 型；成员判定是另一回事——下一课 CYK。</p><p>CFL 泵的两段 \\(v,x\\) 对应树上一次可重复。单栈只能「一对」计数一起动，三计数因此是标准靶。成员判定不是本课任务，下一课 CYK 才接收。</p><p><span class="marginnote">用泵引理时记住「对手论证」的分工：泵长 \\(p\\) 是对手给的，切法 \\(uvwxy\\) 也归对手挑；你手里只有 \\(i\\)。只要存在一个 \\(i\\) 能把每种切法都打出语言外，你就赢了——所以证明里反复出现「对任意切法，取 \\(i=2\\)」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CFL 长串可同时泵两段；\\(a^nb^nc^n\\) 是标准非 CFL。</li><li>与正则交仍 CFL，可先切片再泵。</li><li>可泵不是充要；Ogden 是加强。</li><li>出处：Bar-Hillel, Perles and Shamir, 1961；Sipser。</li></ul>',7))])}const h=A(d,[["render",C]]);export{L as __pageData,h as default};
